package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import java.util.zip.ZipException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class X7875_NewUnix_equals_TriageGen2Test {

    /**
     * Helper method to set private fields via reflection since 
     * the constructor is empty and fields are not provided via setters.
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testEquals_NullObject() {
        X7875_NewUnix x1 = new X7875_NewUnix();
        Assert.assertFalse("equals(null) should return false", x1.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        X7875_NewUnix x1 = new X7875_NewUnix();
        String differentObj = "not an X7875_NewUnix";
        Assert.assertFalse("equals(different class) should return false", x1.equals(differentObj));
    }

    @Test
    public void testEquals_Success() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        X7875_NewUnix x2 = new X7875_NewUnix();

        // Using reflection to set the fields based on the equals logic: 
        // version (int/long?), uid (Object/Long?), gid (Object/Long?)
        // Based on the code: version == xf.version && uid.equals(xf.uid) && gid.equals(xf.gid)
        // Based on the presence of getUID/getGID returning long, but equals using .equals() on uid/gid,
        // it implies uid and gid are stored as Objects (likely Long) in the class.

        setPrivateField(x1, "version", 1);
        setPrivateField(x1, "uid", 1000L);
        setPrivateField(x1, "gid", 1000L);

        setPrivateField(x2, "version", 1);
        setPrivateField(x2, "uid", 1000L);
        setPrivateField(x2, "gid", 1000L);

        Assert.assertTrue("Identical objects should return true", x1.equals(x2));
    }

    @Test
    public void testEquals_DifferentVersion() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        X7875_NewUnix x2 = new X7875_NewUnix();

        setPrivateField(x1, "version", 1);
        setPrivateField(x1, "uid", 1000L);
        setPrivateField(x1, "gid", 1000L);

        setPrivateField(x2, "version", 2); // Different version
        setPrivateField(x2, "uid", 1000L);
        setPrivateField(x2, "gid", 1000L);

        Assert.assertFalse("Different version should return false", x1.equals(x2));
    }

    @Test
    public void testEquals_DifferentUid() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        X7875_NewUnix x2 = new X7875_NewUnix();

        setPrivateField(x1, "version", 1);
        setPrivateField(x1, "uid", 1000L);
        setPrivateField(x1, "gid", 1000L);

        setPrivateField(x2, "version", 1);
        setPrivateField(x2, "uid", 2000L); // Different UID
        setPrivateField(x2, "gid", 1000L);

        Assert.assertFalse("Different UID should return false", x1.equals(x2));
    }

    @Test
    public void testEquals_DifferentGid() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        X7875_NewUnix x2 = new X7875_NewUnix();

        setPrivateField(x1, "version", 1);
        setPrivateField(x1, "uid", 1000L);
        setPrivateField(x1, "gid", 1000L);

        setPrivateField(x2, "version", 1);
        setPrivateField(x2, "uid", 1000L);
        setPrivateField(x2, "gid", 2000L); // Different GID

        Assert.assertFalse("Different GID should return false", x1.equals(x2));
    }

    @Test
    public void testEquals_Self() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        setPrivateField(x1, "version", 1);
        setPrivateField(x1, "uid", 1000L);
        setPrivateField(x1, "gid", 1000L);

        Assert.assertTrue("Object should equal itself", x1.equals(x1));
    }
}
